const bodyRegions={arms:{name:'Hands & arms',fields:{leftArm:['Left shoulder',-180,180],leftElbow:['Left elbow',-150,150],rightArm:['Right shoulder',-180,180],rightElbow:['Right elbow',-150,150],handOpen:['Open hands',0,1,.05]}},legs:{name:'Legs',fields:{leftLeg:['Left hip',-120,120],leftKnee:['Left knee',-150,150],rightLeg:['Right hip',-120,120],rightKnee:['Right knee',-150,150]}},head:{name:'Head',fields:{headTilt:['Head tilt',-45,45],headTurn:['Turn head',-1,1,.05],blink:['Eyes closed',0,1,.05],browRaise:['Raise eyebrows',-15,15],browTilt:['Brow angle',-25,25]}}};
