const originalPoseBeforeBodyAnimation=stateAt;function poseBeforeBodyAnimation(o,t){return originalPoseBeforeBodyAnimation(typeof characterAtView==='function'?characterAtView(o,t):o,t)}
function bodyValueAt(track,field,t){const keys=track.keys.filter(k=>Number.isFinite(k.v[field])).sort((a,b)=>a.t-b.t);if(!keys.length||t<keys[0].t)return null;if(t>=keys.at(-1).t)return keys.at(-1).v[field];const i=keys.findIndex(k=>k.t>t),a=keys[i-1],b=keys[i],f=easingAt({ease:track.ease||'smooth'},(t-a.t)/(b.t-a.t));return a.v[field]+(b.v[field]-a.v[field])*f}
