function writeBodyField(o,region,field,value,at=time){const track=bodyTrack(o,region),t=Math.round(at*1000)/1000,base=poseBeforeBodyAnimation(o,t);if(!track.keys.some(k=>Number.isFinite(k.v[field]))&&t>.015){let first=track.keys.find(k=>k.t===0);if(!first){first={t:0,v:{}};track.keys.push(first)}first.v[field]=track.mode==='add'?0:poseBeforeBodyAnimation(o,0)[field]}let key=track.keys.find(k=>Math.abs(k.t-t)<.015);if(!key){key={t,v:{}};track.keys.push(key)}key.v[field]=track.mode==='add'?value-base[field]:value;track.keys.sort((a,b)=>a.t-b.t);return key}
