document.querySelector('#easyAnimationLibrary').insertAdjacentHTML('afterbegin','<button id="libraryBodyAnimation">Customize hands, legs & head</button>');
document.body.insertAdjacentHTML('beforeend',`<dialog id="bodyAnimationDialog"><div class="tool-heading"><div><div class="eyebrow">YOUR CHARACTER’S PERFORMANCE</div><h2>Body animation</h2></div><button id="closeBodyAnimation">Done</button></div><div class="body-animation-layout"><div><canvas id="bodyAnimationPreview" width="640" height="360" aria-label="Character movement preview"></canvas><div class="body-time-row"><span id="bodyAnimationClock"></span><input id="bodyAnimationTime" type="range" min="0" max="6" step="0.01" aria-label="Body animation time"></div><div id="bodyAnimationKeys" class="body-animation-keys"></div><button id="playBodyAnimation">Play from here</button></div><div><div id="bodyRegionTabs" class="body-region-tabs">${Object.entries(bodyRegions).map(([id,r])=>'<button data-body-region="'+id+'">'+r.name+'</button>').join('')}</div><label>Motion<select id="bodyAnimationMode"><option value="replace">My keyframes</option><option value="add">Blend with automatic</option></select></label><label>Between keys<select id="bodyAnimationEase"><option value="smooth">Smooth</option><option value="linear">Even speed</option><option value="hold">Hold pose</option></select></label><div id="bodyAnimationFields"></div><div class="body-animation-actions"><button id="addBodyAnimationKey" class="primary">＋ Pose key</button><button id="deleteBodyAnimationKey">Delete key</button></div><div id="bodyAnimationPresets"></div><details><summary>Part options</summary><button id="clearBodyAnimation">Reset this part</button><button id="editBodyRig">Edit cut-outs & joints</button></details><p class="note">Move the time slider, then adjust a joint to save its motion. Each part has separate keys. “Blend with automatic” adds your changes to walking or reactions. Hand and leg dragging on the main canvas also updates these keys.</p></div></div></dialog>`);
function bodyEditorObject(){return current().id===bodyEditorScene?current().objects.find(o=>o.id===bodyEditorActor):null}
function commitBodyEditor(){if(bodyEditorDirty){bodyEditorDirty=false;save();renderTimeline()}}
function paintBodyPreview(){if(!bodyEditorObject())return;renderSceneFrame($('bodyAnimationPreview').getContext('2d'),current(),time);$('bodyAnimationClock').textContent=time.toFixed(2)+'s / '+current().duration.toFixed(1)+'s';$('bodyAnimationTime').value=time;draw()}
function renderBodyEditor(){const o=bodyEditorObject();if(!o)return;const track=o.bodyAnimation?.[bodyRegion],v=stateAt(o,time),fields=$('bodyAnimationFields');fields.replaceChildren();document.querySelectorAll('[data-body-region]').forEach(b=>b.classList.toggle('active',b.dataset.bodyRegion===bodyRegion));$('bodyAnimationMode').value=track?.mode||'replace';$('bodyAnimationEase').value=track?.ease||'smooth';let available=0;for(const[field,[name,min,max,step]]of Object.entries(bodyRegions[bodyRegion].fields)){if(!bodyFieldAvailable(o,field))continue;available++;const label=document.createElement('label');label.className='body-joint-field';const text=document.createElement('span');text.textContent=name;const input=document.createElement('input');input.type='range';input.min=min;input.max=max;input.step=step||1;input.value=v[field];input.dataset.bodyField=field;input.setAttribute('aria-label',name);const output=document.createElement('output');output.textContent=Number(v[field]).toFixed(step&&step<1?2:0);input.oninput=()=>{if(o.locked)return;writeBodyField(o,bodyRegion,field,+input.value);output.textContent=input.value;bodyEditorDirty=true;paintBodyPreview()};input.onchange=()=>{commitBodyEditor();renderBodyKeys()};label.append(text,input,output);fields.append(label)}if(!available){const note=document.createElement('p');note.className='note';note.textContent='Set up these body parts and their joints in the picture rig first. Eye and brow controls need marked face areas.';fields.append(note)}$('editBodyRig').hidden=o.type!=='puppet';const presets=$('bodyAnimationPresets');presets.replaceChildren();if(bodyRegion==='head'){if(bodyFieldAvailable(o,'headTilt'))presets.append(storyButton('Nod',()=>bodyMotionPreset('nod')));if(bodyFieldAvailable(o,'headTurn'))presets.append(storyButton('Shake head',()=>bodyMotionPreset('shake')))}else if(bodyRegion==='arms'&&(bodyFieldAvailable(o,'rightArm')||bodyFieldAvailable(o,'leftArm')))presets.append(storyButton('Wave',()=>bodyMotionPreset('wave')));renderBodyKeys();paintBodyPreview()}
function renderBodyKeys(){const o=bodyEditorObject(),list=$('bodyAnimationKeys');list.replaceChildren();for(const k of o?.bodyAnimation?.[bodyRegion]?.keys||[]){const b=document.createElement('button');b.textContent=k.t.toFixed(2)+'s';b.className=Math.abs(k.t-time)<.02?'active':'';b.onclick=()=>{commitBodyEditor();time=k.t;renderBodyEditor()};list.append(b)}if(!list.children.length)list.textContent='No custom keys for this part yet.'}
async function openBodyAnimation(o=object()){if(!isAnimatedCharacter(o)||o.locked)return toast('Select an unlocked character or picture rig.');stop();if(pathEditor)finishPathEditing();bodyEditorActor=o.id;bodyEditorScene=current().id;bodyEditorDirty=false;$('bodyAnimationTime').max=current().duration;renderBodyEditor();$('bodyAnimationDialog').showModal();const scene=current();await Promise.all([scene.backgroundImage,...scene.objects.flatMap(o=>o.type==='image'?[o.src]:o.type==='puppet'?[...o.parts.map(p=>p.src),...puppetFaceSources(o),...Object.values(o.mouth?.sprites||{})]:o.type==='flipbook'?o.frames.map(f=>f.src):[])].filter(Boolean).map(src=>imageReady(src).catch(()=>{})));if(current()===scene&&$('bodyAnimationDialog').open)paintBodyPreview()}
$('libraryBodyAnimation').onclick=()=>openBodyAnimation();const controlsBeforeBodyEditor=renderControls;renderControls=function(){controlsBeforeBodyEditor();if(!isAnimatedCharacter(object()))return;const b=document.createElement('button');b.id='openBodyAnimation';b.textContent='Customize body animation';b.disabled=!!object().locked;b.onclick=()=>openBodyAnimation();const easy=$('walkCharacterTo')?.closest('details');if(easy)easy.querySelector('summary').after(b)};
document.querySelectorAll('[data-body-region]').forEach(b=>b.onclick=()=>{commitBodyEditor();bodyRegion=b.dataset.bodyRegion;renderBodyEditor()});$('bodyAnimationTime').oninput=e=>{commitBodyEditor();time=+e.target.value;renderBodyEditor()};$('closeBodyAnimation').onclick=()=>$('bodyAnimationDialog').close();$('bodyAnimationDialog').addEventListener('close',()=>{commitBodyEditor();render()});$('playBodyAnimation').onclick=()=>{commitBodyEditor();$('bodyAnimationDialog').close();previewStoryRange(time,current().duration,bodyEditorActor)};
$('addBodyAnimationKey').onclick=()=>{const o=bodyEditorObject(),v=stateAt(o,time);if(!o||o.locked)return;for(const field of Object.keys(bodyRegions[bodyRegion].fields))if(bodyFieldAvailable(o,field)&&field!=='blink')writeBodyField(o,bodyRegion,field,v[field]);bodyEditorDirty=true;commitBodyEditor();renderBodyEditor()};$('deleteBodyAnimationKey').onclick=()=>{const o=bodyEditorObject(),track=o?.bodyAnimation?.[bodyRegion];if(!track||o.locked)return;track.keys=track.keys.filter(k=>Math.abs(k.t-time)>.02);bodyEditorDirty=true;commitBodyEditor();renderBodyEditor()};$('clearBodyAnimation').onclick=()=>{const o=bodyEditorObject();if(!o||o.locked)return;if(o.bodyAnimation)delete o.bodyAnimation[bodyRegion];bodyEditorDirty=true;commitBodyEditor();renderBodyEditor()};$('editBodyRig').onclick=()=>{const o=bodyEditorObject();$('bodyAnimationDialog').close();openImageRig(o)};
$('bodyAnimationMode').onchange=e=>{const o=bodyEditorObject();if(!o||o.locked)return;commitBodyEditor();const track=bodyTrack(o,bodyRegion),mode=e.target.value;if(track.mode!==mode){for(const k of track.keys){const base=poseBeforeBodyAnimation(o,k.t);for(const field of Object.keys(k.v))k.v[field]+=mode==='add'?-base[field]:base[field]}track.mode=mode;save();renderBodyEditor()}};$('bodyAnimationEase').onchange=e=>{const o=bodyEditorObject();if(!o||o.locked)return;bodyTrack(o,bodyRegion).ease=e.target.value;save()};
function bodyMotionPreset(kind){const o=bodyEditorObject();if(!o||o.locked)return;commitBodyEditor();const start=time,duration=kind==='wave'?1.4:.8,end=start+duration;if(end>60)return toast('Move the playhead earlier; this gesture exceeds 60 seconds.');if(end>clipEnd(o)&&clipEnd(o)<current().duration)return toast('Extend this character’s clip before adding the gesture.');if(end>current().duration){const old=current().duration,anchors=sceneAudioAnchors();current().duration=end;if(o.out===old)o.out=end;placeSceneAudio(anchors);$('bodyAnimationTime').max=end}const v=stateAt(o,start),side=bodyFieldAvailable(o,'rightArm')?'right':'left',a=side+'Arm',e=side+'Elbow',sign=side==='right'?-1:1,poses=kind==='nod'?[{headTilt:v.headTilt},{headTilt:v.headTilt-12},{headTilt:v.headTilt+8},{headTilt:v.headTilt}]:kind==='shake'?[{headTurn:v.headTurn},{headTurn:-.7},{headTurn:.7},{headTurn:v.headTurn}]:[{[a]:v[a],[e]:v[e]},{[a]:140*sign,[e]:20*sign},{[a]:140*sign,[e]:60*sign},{[a]:140*sign,[e]:20*sign},{[a]:v[a],[e]:v[e]}];const track=bodyTrack(o,bodyRegion),affected=new Set(poses.flatMap(p=>Object.keys(p)));for(const k of track.keys)if(k.t>=start-.01&&k.t<=end+.01)for(const field of affected)delete k.v[field];track.keys=track.keys.filter(k=>Object.keys(k.v).length);for(const [i,pose]of poses.entries())for(const[field,value]of Object.entries(pose))if(bodyFieldAvailable(o,field)){const at=start+duration*i/(poses.length-1),target=track.mode==='add'&&(i===0||i===poses.length-1)?poseBeforeBodyAnimation(o,at)[field]:value;writeBodyField(o,bodyRegion,field,target,at)}save();renderBodyEditor();renderTimeline()}
const jointsBeforeBodyAnimation=poseJoint;poseJoint=function(o,key,p,initial,keyBase){let region,fields;if(o.type==='puppet'){const part=o.parts.find(p=>'part:'+p.id===key);if(!part)return jointsBeforeBodyAnimation(o,key,p,initial,keyBase);const side=part.channel.startsWith('left')?'left':'right';if(['leftArm','leftElbow','rightArm','rightElbow'].includes(part.channel)){region='arms';fields=[side+'Arm',side+'Elbow']}else if(['leftLeg','leftKnee','rightLeg','rightKnee'].includes(part.channel)){region='legs';fields=[side+'Leg',side+'Knee']}else{region='head';fields=['headTilt']}}else if(key==='head'){region='head';fields=['headTilt']}else{const side=key.startsWith('left')?'left':'right';region=key.endsWith('Foot')||key.endsWith('Knee')?'legs':'arms';fields=region==='legs'?[side+'Leg',side+'Knee']:[side+'Arm',side+'Elbow']}if(!o.bodyAnimation?.[region]?.keys.length)return jointsBeforeBodyAnimation(o,key,p,initial,keyBase);if(motionTake?.o===o&&motionTake.mode==='joint'){motionTake.bodyRegion=region;motionTake.bodyFields=fields;return jointsBeforeBodyAnimation(o,key,p,initial,keyBase)}const before=structuredClone(o.keys);jointsBeforeBodyAnimation(o,key,p,initial,keyBase);const at=o.keys.find(k=>Math.abs(k.t-time)<.015)?.v;o.keys=before;if(at)for(const field of fields)writeBodyField(o,region,field,at[field])};
function finishBodyRecording(take,end){if(!take.bodyRegion)return;take.o.keys=structuredClone(take.before.keys);take.o.bodyAnimation=structuredClone(take.before.bodyAnimation);const track=bodyTrack(take.o,take.bodyRegion);for(const k of track.keys)if(k.t>=take.start-.015&&k.t<=end+.015)for(const field of take.bodyFields)delete k.v[field];track.keys=track.keys.filter(k=>Object.keys(k.v).length);track.ease='linear';for(const sample of take.samples)for(const field of take.bodyFields)if(Number.isFinite(sample.v[field]))writeBodyField(take.o,take.bodyRegion,field,sample.v[field],sample.t)}
