const timelineBeforeBodyAnimation=renderTimeline;renderTimeline=function(){timelineBeforeBodyAnimation();if(timelineDrag)return;const offset=sceneOffset();for(const o of current().objects)for(const[name,track]of Object.entries(o.bodyAnimation||{})){if(!track.keys.length)continue;const row=lane(bodyRegions[name].name+' · '+o.name,'body-animation-track');for(const k of track.keys){const b=document.createElement('button');b.className='body-timeline-key';b.style.left=(offset+k.t)*timelineZoom+'px';b.textContent='◆';b.title=bodyRegions[name].name+' · '+k.t.toFixed(2)+'s';b.disabled=!!o.locked;b.onclick=()=>{stop();selectLayers([o.id]);time=k.t;render()};b.onkeydown=e=>{if(o.locked||!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();e.stopPropagation();k.t=clamp(k.t+(e.key==='ArrowRight'?1:-1)/30,0,current().duration);track.keys.sort((a,b)=>a.t-b.t);time=k.t;save();render()};row.area.append(b)}}};
const bodyAnimationValidator=valid;valid=function(p){try{return bodyAnimationValidator(p)&&p.scenes.every(s=>s.objects.every(o=>!o.bodyAnimation||isAnimatedCharacter(o)&&Object.entries(o.bodyAnimation).every(([name,track])=>Object.hasOwn(bodyRegions,name)&&['add','replace'].includes(track.mode)&&['smooth','linear','hold'].includes(track.ease)&&Array.isArray(track.keys)&&track.keys.length<=500&&track.keys.every(k=>k&&Number.isFinite(k.t)&&k.t>=0&&k.t<=s.duration+.001&&k.v&&Object.entries(k.v).length>0&&Object.entries(k.v).every(([field,v])=>Object.hasOwn(bodyRegions[name].fields,field)&&Number.isFinite(v)&&Math.abs(v)<=720)))))}catch{return false}};
